import { generateBookCover, generateBookSummary } from '../services/geminiService';

const DEFAULT_STATUS_CONFIGS: StatusConfigs = {
  [BookStatus.Reading]: { label: 'Lendo atualmente', color: 'blue' },
  [BookStatus.Read]: { label: 'Já Lido', color: 'emerald' },
  [BookStatus.TBR]: { label: 'Não lido', color: 'slate' },
  [BookStatus.Wishlist]: { label: 'Lista de Desejos', color: 'rose' },
};

const INITIAL_BOOKS: Book[] = [
  {
    id: '1',
    title: 'O Senhor dos Anéis - A Sociedade do Anel',
    author: 'J.R.R. Tolkien',
    pages: 434,
    genre: 'Aventura',
