    summary: 'Em uma terra fantástica e única, um hobbit recebe de presente de seu tio um anel mágico e maligno que precisa ser destruído antes que caia nas mãos do mal.',
  },
  { 
    id: '2', 
    title: 'Duna', 
    author: 'Frank Herbert', 
    pages: 688, 
    genre: 'Ficção', 
    type: BookType.Book, 
    status: BookStatus.Read, 
    rating: 9, 
    yearRead: 2024, 
    monthRead: 'Julho', 
    dateAdded: '2024-02-10',
    dateStarted: '2024-06-20',
    dateFinished: '2024-07-15'
  }
];

export const useBookData = () => {
  const [books, setBooks] = useState<Book[]>(() => {
    const saved = localStorage.getItem('bibliotech_books');
    return saved ? JSON.parse(saved) : INITIAL_BOOKS;
  });

  const [statusConfigs, setStatusConfigs] = useState<StatusConfigs>(() => {
    const saved = localStorage.getItem('bibliotech_status_configs');
    return saved ? JSON.parse(saved) : DEFAULT_STATUS_CONFIGS;
  });

  const [dateFilter, setDateFilter] = useState<DateFilter>('thisYear');

  useEffect(() => {
    localStorage.setItem('bibliotech_books', JSON.stringify(books));
  }, [books]);

  useEffect(() => {
    localStorage.setItem('bibliotech_status_configs', JSON.stringify(statusConfigs));
  }, [statusConfigs]);

  const stats: ReadingStats = useMemo(() => {
    const currentYear = new Date().getFullYear();
    const readBooks = books.filter(b => b.status === BookStatus.Read && b.yearRead);
    const filteredReadBooks = dateFilter === 'thisYear' ? readBooks.filter(b => b.yearRead === currentYear) : readBooks;

    const yearly = {
        booksRead: filteredReadBooks.length,
        pagesRead: filteredReadBooks.reduce((acc, book) => acc + book.pages, 0),
        avgRating: filteredReadBooks.length > 0 ? filteredReadBooks.reduce((acc, book) => acc + (book.rating || 0), 0) / filteredReadBooks.length : 0,
    };

    return { 
      tbrCount: books.filter(b => b.status === BookStatus.TBR).length, 
      wishlistCount: books.filter(b => b.status === BookStatus.Wishlist).length, 
      yearly, 
      monthly: [], // Simplified for this update
      byType: [] // Simplified for this update
    };
  }, [books, dateFilter]);

  const currentlyReading = useMemo(() => books.find(book => book.status === BookStatus.Reading) || null, [books]);

  const updateStatusConfig = (status: BookStatus, config: Partial<StatusConfig>) => {
    setStatusConfigs(prev => ({
      ...prev,
      [status]: { ...prev[status], ...config }
    }));
  };

  const addBook = useCallback(async (newBookData: NewBook) => {
    const id = Date.now().toString();
    const summary = newBookData.summary || await generateBookSummary(newBookData.title, newBookData.author);
    const coverImageUrl = newBookData.coverImageUrl || await generateBookCover(newBookData.title, newBookData.genre, newBookData.type);

    const newBook: Book = { ...newBookData, id, summary, coverImageUrl };
    setBooks(prev => [...prev, newBook]);
  }, []);

  const updateBook = useCallback((updatedBook: Book) => {
    setBooks(prev => prev.map(book => book.id === updatedBook.id ? updatedBook : book));
  }, []);

  const deleteBook = useCallback((bookId: string) => {
    setBooks(prev => prev.filter(book => book.id !== bookId));
  }, []);

  return { 
    books, 
    statusConfigs, 
    updateStatusConfig, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter 
  };
};

