import React, { useState, useMemo } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { Settings } from './components/Settings';

export default function App() {
  const { 
    books, 
    statusConfigs, 
    updateStatusConfig, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter 
  } = useBookData();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist' | 'settings'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();

  const handleAddBook = (newBook: NewBook) => {
    addBook(newBook);
    setIsModalOpen(false);
    setEditingBook(null);
  };

  const handleUpdateBook = (updatedBook: Book) => {
    updateBook(updatedBook);
    setIsModalOpen(false);
    setEditingBook(null);
  };

  const openAddModal = (defaultStatus?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(defaultStatus);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingBook(null);
  };

  const shelfBooks = useMemo(() => books.filter(book => book.status !== BookStatus.Wishlist), [books]);
  const wishlistBooks = useMemo(() => books.filter(book => book.status === BookStatus.Wishlist), [books]);

  const [isFading, setIsFading] = useState(false);

  const handleSetView = (newView: typeof view) => {
    if (view !== newView) {
      setIsFading(true);
      setTimeout(() => {
        setView(newView);
        setIsFading(false);
      }, 200);
    }
  };

  const renderContent = () => {
    switch(view) {
      case 'dashboard':
        return <Dashboard 
                  stats={stats} 
                  currentlyReading={currentlyReading} 
                  updateBook={updateBook}
                  dateFilter={dateFilter}
                  setDateFilter={setDateFilter} 
                />;
      case 'list':
        return <BookList 
                  books={shelfBooks} 
                  onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
                  onDelete={setDeletingBook} 
                  statusConfigs={statusConfigs}
                />;
      case 'wishlist':
        return <Wishlist 
                  books={wishlistBooks} 
                  onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
                  onDelete={setDeletingBook} 
                  onMoveToShelf={(b) => updateBook({ ...b, status: BookStatus.TBR })} 
                  onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)}
                  statusConfigs={statusConfigs}
                />;
      case 'settings':
        return <Settings 
                  statusConfigs={statusConfigs} 
                  onUpdateConfig={updateStatusConfig} 
                />;
      default:
        return null;
    }
  }

  return (
    <div className="min-h-screen bg-background text-text-main">
      <Header view={view} setView={handleSetView} />
      <main className={`p-4 md:p-8 transition-all duration-300 transform ${isFading ? 'opacity-0 -translate-y-2' : 'opacity-100 translate-y-0'}`}>
        {renderContent()}
      </main>

      {view !== 'settings' && (
        <button
          onClick={() => openAddModal()}
          className="fixed bottom-8 right-8 bg-primary text-background p-4 rounded-full shadow-lg hover:bg-blue-700 transition-all z-40"
        >
          <PlusIcon className="h-8 w-8" />
        </button>
      )}

      {isModalOpen && (
        <AddBookModal
          onClose={closeModal}
          onAddBook={handleAddBook}
          onUpdateBook={handleUpdateBook}
          bookToEdit={editingBook}
          defaultStatus={defaultStatusForModal}
          existingBooks={books}
          statusConfigs={statusConfigs}
        />
      )}

      {deletingBook && (
        <ConfirmationModal
          isOpen={!!deletingBook}
          onClose={() => setDeletingBook(null)}
          onConfirm={() => { deleteBook(deletingBook.id); setDeletingBook(null); }}
          title="Confirmar Exclusão"
          message={`Tem certeza que deseja excluir "${deletingBook.title}"?`}
        />
      )}
    </div>
  );
}

