    let result = [...books];
    if (sortBy === 'title') result.sort((a, b) => a.title.localeCompare(b.title));
    else result.sort((a, b) => b.dateAdded.localeCompare(a.dateAdded));

    if (statusFilter !== 'all') result = result.filter(book => book.status === statusFilter);
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      result = result.filter(book => book.title.toLowerCase().includes(query) || book.author.toLowerCase().includes(query));
    }
    return result;
  }, [books, searchQuery, statusFilter, sortBy]);

  const filterButtons = [
    { label: 'Todos', value: 'all' as FilterStatus },
    { label: statusConfigs[BookStatus.Reading].label, value: BookStatus.Reading as FilterStatus },
    { label: statusConfigs[BookStatus.Read].label, value: BookStatus.Read as FilterStatus },
    { label: statusConfigs[BookStatus.TBR].label, value: BookStatus.TBR as FilterStatus },
  ];

  return (
    <div className="space-y-8">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div>
          <h2 className="text-3xl font-bold font-serif text-slate-900 tracking-tight">
            Minha Estante <span className="text-primary/50 text-xl ml-2">({filteredBooks.length})</span>
          </h2>
          <p className="text-slate-500 text-sm font-medium mt-1">Gerencie seus livros físicos e digitais.</p>
        </div>
        <input
            type="text"
            placeholder="Pesquisar..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full lg:w-96 bg-white border border-slate-200 rounded-2xl py-3 px-4 text-slate-900 focus:ring-4 focus:ring-primary/10 focus:border-primary outline-none transition-all shadow-sm"
          />
      </div>

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-2 border-b border-slate-100">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mr-2">Filtrar:</span>
          {filterButtons.map((btn) => (
            <button
              key={btn.value}
              onClick={() => setStatusFilter(btn.value)}
              className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all border ${
                statusFilter === btn.value
                  ? 'bg-primary text-white border-primary shadow-lg shadow-primary/20'
                  : 'bg-white text-slate-500 border-slate-200 hover:border-primary/30'
              }`}
            >
              {btn.label}
            </button>
          ))}
        </div>

        <select 
            value={sortBy} 
            onChange={(e) => setSortBy(e.target.value as SortOrder)}
            className="bg-white border border-slate-200 rounded-xl px-3 py-1.5 text-[10px] font-black uppercase tracking-wider text-slate-600 outline-none"
          >
            <option value="dateAdded">Mais Recentes</option>
            <option value="title">Título (A-Z)</option>
        </select>
      </div>

      <div className="space-y-4">
        {filteredBooks.map(book => (
            <BookListItem key={book.id} book={book} onEdit={onEdit} onDelete={onDelete} statusConfigs={statusConfigs} />
        ))}
      </div>
    </div>
  );
};

import React, { useState, useCallback, useMemo } from 'react';
import type { NewBook, Book, StatusConfigs } from '../types';
import { BookStatus, BookType, GENRES } from '../types';
import { XMarkIcon, BookOpenIcon } from './Icons';
import { generateBookSummary, generateBookCover } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => void;
  onUpdateBook: (book: Book) => void;
  bookToEdit?: Book | null;
  defaultStatus?: BookStatus;
  existingBooks: Book[];
  statusConfigs: StatusConfigs;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ onClose, onAddBook, onUpdateBook, bookToEdit, defaultStatus, existingBooks, statusConfigs }) => {
  const isEditMode = !!bookToEdit;
  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [author, setAuthor] = useState(bookToEdit?.author || '');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [genre, setGenre] = useState(bookToEdit?.genre || '');
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
