import React, { useState, useMemo } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';

export default function App() {
  const { 
    books, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter,
    customRange,
    setCustomRange 
  } = useBookData();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();

  const handleAddBook = (newBook: NewBook) => {
    addBook(newBook);
    setIsModalOpen(false);
    setEditingBook(null);
  };

  const handleUpdateBook = (updatedBook: Book) => {
    updateBook(updatedBook);
    setIsModalOpen(false);
    setEditingBook(null);
  };

  const openAddModal = (defaultStatus?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(defaultStatus);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingBook(null);
    setDefaultStatusForModal(undefined);
  };

  const shelfBooks = useMemo(() => books.filter(book => book.status !== BookStatus.Wishlist), [books]);
  const wishlistBooks = useMemo(() => books.filter(book => book.status === BookStatus.Wishlist), [books]);

  const [isFading, setIsFading] = useState(false);

  const handleSetView = (newView: 'dashboard' | 'list' | 'wishlist') => {
    if (view !== newView) {
      setIsFading(true);
      setTimeout(() => {
        setView(newView);
        setIsFading(false);
      }, 200);
    }
  };

  const renderContent = () => {
    switch(view) {
      case 'dashboard':
        return <Dashboard 
                  stats={stats} 
                  currentlyReading={currentlyReading} 
                  updateBook={updateBook}
                  dateFilter={dateFilter}
                  setDateFilter={setDateFilter} 
                  customRange={customRange}
                  setCustomRange={setCustomRange}
                />;
      case 'list':
        return <BookList books={shelfBooks} onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} onDelete={setDeletingBook} />;
      case 'wishlist':
        return <Wishlist 
                  books={wishlistBooks} 
                  onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
                  onDelete={setDeletingBook} 
                  onMoveToShelf={(b) => updateBook({ ...b, status: BookStatus.TBR })} 
                  onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)}
                />;
      default:
        return null;
    }
  }

  return (
    <div className="min-h-screen bg-background text-text-main">
      <Header view={view} setView={handleSetView} />
      <main className={`p-4 md:p-8 transition-all duration-300 transform ${isFading ? 'opacity-0 -translate-y-2' : 'opacity-100 translate-y-0'}`}>
        {renderContent()}
      </main>

      <button
        onClick={() => openAddModal()}
        className="fixed bottom-8 right-8 bg-primary text-background p-4 rounded-full shadow-lg hover:bg-blue-700 transition-all z-40"
      >
        <PlusIcon className="h-8 w-8" />
      </button>

      {isModalOpen && (
        <AddBookModal
          onClose={closeModal}
          onAddBook={handleAddBook}
          onUpdateBook={handleUpdateBook}
          bookToEdit={editingBook}
          defaultStatus={defaultStatusForModal}
          existingBooks={books}
        />
      )}

      {deletingBook && (
        <ConfirmationModal
          isOpen={!!deletingBook}
          onClose={() => setDeletingBook(null)}
          onConfirm={() => { deleteBook(deletingBook.id); setDeletingBook(null); }}
          title="Confirmar Exclusão"
          message={`Tem certeza que deseja excluir "${deletingBook.title}"?`}
        />
      )}
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import type { Book } from '../types';
import { BookStatus, GENRES } from '../types';
import { BookListItem } from './BookListItem';
import { XMarkIcon } from './Icons';

interface BookListProps {
  books: Book[];
  onEdit: (book: Book) => void;
  onDelete: (book: Book) => void;
}

type FilterStatus = 'all' | BookStatus;
type SortOrder = 'title' | 'dateAdded';

export const BookList: React.FC<BookListProps> = ({ books, onEdit, onDelete }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<FilterStatus>('all');
  const [sortBy, setSortBy] = useState<SortOrder>('dateAdded');
  const [selectedGenres, setSelectedGenres] = useState<string[]>([]);

  const toggleGenre = (genre: string) => {
    setSelectedGenres(prev => 
      prev.includes(genre) 
        ? prev.filter(g => g !== genre) 
        : [...prev, genre]
    );
  };

  const filteredBooks = useMemo(() => {
    let result = [...books];

    // Ordenação inicial
    if (sortBy === 'title') {
      result.sort((a, b) => a.title.localeCompare(b.title));
    } else {
      result.sort((a, b) => b.dateAdded.localeCompare(a.dateAdded));
    }

    // Filtrar por Status
    if (statusFilter !== 'all') {
      result = result.filter(book => book.status === statusFilter);
    }

    // Filtrar por Busca
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      result = result.filter(book =>
        book.title.toLowerCase().includes(query) ||
        book.author.toLowerCase().includes(query)
      );
    }

    // Filtrar por Gêneros (Lógica: Deve conter pelo menos um dos gêneros selecionados)
    if (selectedGenres.length > 0) {
      result = result.filter(book => {
        const bookGenres = book.genre.split(',').map(g => g.trim().toLowerCase());
        return selectedGenres.some(sg => bookGenres.includes(sg.toLowerCase()));
      });
    }

    return result;
  }, [books, searchQuery, statusFilter, sortBy, selectedGenres]);

  const filterButtons = [
    { label: 'Todos', value: 'all' as FilterStatus },
    { label: 'Lendo', value: BookStatus.Reading as FilterStatus },
    { label: 'Lidos', value: BookStatus.Read as FilterStatus },
    { label: 'Quero Ler', value: BookStatus.TBR as FilterStatus },
  ];

  return (
    <div className="space-y-8">
      {/* Header e Busca */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div>
          <h2 className="text-3xl font-bold font-serif text-slate-900 tracking-tight">
            Minha Estante <span className="text-primary/50 text-xl ml-2">({filteredBooks.length})</span>
          </h2>
          <p className="text-slate-500 text-sm font-medium mt-1">Gerencie seus livros físicos e digitais.</p>
        </div>

        <div className="relative w-full lg:w-96 group">
          <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-slate-400 group-focus-within:text-primary transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </div>
          <input
            type="text"
            placeholder="Título ou autor..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-white border border-slate-200 rounded-2xl py-3 pl-11 pr-4 text-slate-900 placeholder:text-slate-400 focus:ring-4 focus:ring-primary/10 focus:border-primary outline-none transition-all shadow-sm"
          />
        </div>
      </div>

      {/* Controles de Filtragem */}
      <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-soft space-y-6">
        {/* Status e Ordenação */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-50">
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mr-2">Status:</span>
            {filterButtons.map((btn) => (
              <button
                key={btn.value}
                onClick={() => setStatusFilter(btn.value)}
                className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all border ${
                  statusFilter === btn.value
                    ? 'bg-primary text-white border-primary shadow-lg shadow-primary/20'
                    : 'bg-slate-50 text-slate-500 border-slate-100 hover:border-primary/30'
                }`}
              >
                {btn.label}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-3">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Ordenar:</span>
            <select 
              value={sortBy} 
              onChange={(e) => setSortBy(e.target.value as SortOrder)}
              className="bg-slate-50 border border-slate-100 rounded-xl px-3 py-1.5 text-[10px] font-black uppercase tracking-wider text-slate-600 outline-none focus:ring-2 focus:ring-primary/10 transition-all cursor-pointer"
            >
              <option value="dateAdded">Mais Recentes</option>
              <option value="title">Título (A-Z)</option>
            </select>
          </div>
        </div>

        {/* Filtro de Gêneros */}
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Filtrar Gêneros:</span>
              {selectedGenres.length > 0 && (
                <button 
                  onClick={() => setSelectedGenres([])}
                  className="text-[9px] font-bold text-primary uppercase tracking-wider hover:underline"
                >
                  Limpar todos
                </button>
              )}
            </div>
            <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">
              {selectedGenres.length} selecionado(s)
            </span>
          </div>

          <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto pr-2 custom-scrollbar">
            {GENRES.map((genre) => {
              const isSelected = selectedGenres.includes(genre);
              return (
                <button
                  key={genre}
                  onClick={() => toggleGenre(genre)}
                  className={`px-3 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-widest transition-all border ${
                    isSelected
                      ? 'bg-primary/10 text-primary border-primary/30 scale-95 shadow-inner'
                      : 'bg-white text-slate-500 border-slate-200 hover:border-slate-300'
                  }`}
                >
                  {isSelected && <span className="mr-1">✓</span>}
                  {genre}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Lista de Livros */}
      <div className="space-y-4">
        {filteredBooks.length > 0 ? (
          filteredBooks.map(book => (
            <BookListItem key={book.id} book={book} onEdit={onEdit} onDelete={onDelete} />
          ))
        ) : (
          <div className="text-center py-20 bg-white rounded-[2.5rem] border-2 border-dashed border-slate-100">
            <div className="bg-slate-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                </svg>
            </div>
            <h3 className="text-lg font-bold text-slate-900">Nenhum livro encontrado</h3>
            <p className="text-slate-400 mt-1 max-w-xs mx-auto">Tente ajustar sua busca ou mudar os filtros selecionados.</p>
            {(statusFilter !== 'all' || searchQuery !== '' || selectedGenres.length > 0) ? (
                <button 
                    onClick={() => { setStatusFilter('all'); setSearchQuery(''); setSelectedGenres([]); }}
                    className="mt-6 text-primary font-bold text-sm hover:underline"
                >
                    Limpar todos os filtros
                </button>
            ) : null}
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import type { Book, StatusConfigs } from '../types';
import { BookStatus, STATUS_COLORS, STATUS_CONFIGS } from '../types';
import { StarIcon } from './Icons';

interface BookListItemProps {
  book: Book;
  onEdit: (book: Book) => void;
  onDelete: (book: Book) => void;
  statusConfigs?: StatusConfigs;
}

const StarRating: React.FC<{ rating: number }> = ({ rating }) => {
  return (
    <div className="flex items-center gap-0.5">
      {[...Array(10)].map((_, index) => (
        <StarIcon
          key={index}
          className={`h-3.5 w-3.5 ${index < rating ? 'text-amber-400 fill-current' : 'text-slate-200'}`}
        />
      ))}
    </div>
  );
};

const formatDate = (dateStr: string) => {
    if (!dateStr) return '';
    const [year, month, day] = dateStr.split('-');
    return `${day}/${month}/${year}`;
}

// Função auxiliar para gerar cores baseadas no nome do gênero
const getGenreColor = (genre: string) => {
    const palettes = [
        { bg: 'bg-indigo-50', text: 'text-indigo-600', border: 'border-indigo-100' },
        { bg: 'bg-rose-50', text: 'text-rose-600', border: 'border-rose-100' },
        { bg: 'bg-emerald-50', text: 'text-emerald-600', border: 'border-emerald-100' },
        { bg: 'bg-amber-50', text: 'text-amber-600', border: 'border-amber-100' },
        { bg: 'bg-violet-50', text: 'text-violet-600', border: 'border-violet-100' },
        { bg: 'bg-cyan-50', text: 'text-cyan-600', border: 'border-cyan-100' },
        { bg: 'bg-orange-50', text: 'text-orange-600', border: 'border-orange-100' },
        { bg: 'bg-fuchsia-50', text: 'text-fuchsia-600', border: 'border-fuchsia-100' },
    ];

    let hash = 0;
    for (let i = 0; i < genre.length; i++) {
        hash = genre.charCodeAt(i) + ((hash << 5) - hash);
    }
    return palettes[Math.abs(hash) % palettes.length];
};

export const BookListItem: React.FC<BookListItemProps> = ({ book, onEdit, onDelete, statusConfigs = STATUS_CONFIGS }) => {
  const config = statusConfigs[book.status];
  const colorStyles = STATUS_COLORS[config.color as keyof typeof STATUS_COLORS];

  const genresList = book.genre ? book.genre.split(',').map(g => g.trim()).filter(g => g !== '') : [];

  return (
    <article className="bg-white p-6 md:p-7 rounded-[2.5rem] shadow-soft border border-slate-100 flex flex-col md:flex-row items-center gap-8 transition-all duration-500 hover:shadow-xl hover:-translate-y-1.5 hover:border-primary/10 group">

      <div className="relative flex-shrink-0 perspective-1000">
        <div className="relative group/cover transition-transform duration-700 ease-out group-hover:rotate-y-12">
          <img
            src={book.coverImageUrl || `https://picsum.photos/seed/${encodeURIComponent(book.title)}/400/600`}
            alt={book.title}
            className="w-28 h-40 md:w-32 md:h-48 object-cover rounded-2xl shadow-lg"
          />
          <div className="absolute inset-y-0 left-0 w-1.5 bg-gradient-to-r from-black/20 to-transparent rounded-l-2xl"></div>
        </div>
      </div>

      <div className="flex-1 text-center md:text-left min-w-0">
        <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4 mb-2">
            <div className="min-w-0">
                <h3 className="text-2xl font-black text-slate-900 leading-tight font-serif italic group-hover:text-primary transition-colors">
                  {book.title}
                </h3>
                <p className="text-lg text-slate-400 font-semibold">{book.author}</p>
            </div>
            <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest whitespace-nowrap">
               Registrado em {formatDate(book.dateAdded)}
            </span>
        </div>

        <div className="flex flex-wrap justify-center md:justify-start items-center gap-2 mb-6 mt-4">
            <span className={`px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-[0.1em] border shadow-sm ${colorStyles.bg} ${colorStyles.text} ${colorStyles.border}`}>
                {config.label}
            </span>
            <span className="px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-[0.1em] border bg-slate-50 text-slate-500 border-slate-100">
                {book.type}
            </span>

            {/* Renderização aprimorada das tags de gênero */}
            {genresList.map(g => {
              const palette = getGenreColor(g);
              return (
                <span 
                  key={g} 
                  className={`px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-wider border shadow-sm transition-transform hover:scale-105 cursor-default ${palette.bg} ${palette.text} ${palette.border}`}
                >
                    {g}
                </span>
              );
            })}
        </div>

        {book.rating && book.status === BookStatus.Read && (
            <div className="flex justify-center md:justify-start items-center gap-4 mb-4 bg-slate-50/50 p-2 rounded-2xl w-fit">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Avaliação</span>
                <StarRating rating={book.rating} />
            </div>
        )}
      </div>

      <div className="flex flex-row md:flex-col gap-3 w-full md:w-44 mt-4 md:mt-0">
        <button onClick={() => onEdit(book)} className="flex-1 px-6 py-3 text-[11px] font-black rounded-2xl bg-slate-900 text-white hover:bg-primary shadow-lg transition-all active:scale-95 uppercase tracking-widest">
          Editar
        </button>
        <button onClick={() => onDelete(book)} className="flex-1 px-6 py-3 text-[11px] font-black rounded-2xl bg-white text-red-400 hover:bg-red-50 border border-red-100 transition-all active:scale-95 uppercase tracking-widest">
          Excluir
        </button>
      </div>
    </article>
  );
};

