const formatDate = (dateStr: string) => {
    if (!dateStr) return '';
    const [year, month, day] = dateStr.split('-');
    return `${day}/${month}/${year}`;
}

export const WishlistItem: React.FC<WishlistItemProps> = ({ book, onEdit, onDelete, onMoveToShelf }) => {
