import React from 'react';
import { BookOpenIcon, ChartBarIcon, HeartIcon } from './Icons';

interface BottomNavProps {
  view: 'dashboard' | 'list' | 'wishlist';
  setView: (view: 'dashboard' | 'list' | 'wishlist') => void;
}

export const BottomNav: React.FC<BottomNavProps> = ({ view, setView }) => {
  const navItems = [
    { id: 'dashboard', label: 'Início', icon: <ChartBarIcon className="h-6 w-6" /> },
    { id: 'list', label: 'Estante', icon: <BookOpenIcon className="h-6 w-6" /> },
    { id: 'wishlist', label: 'Desejos', icon: <HeartIcon className="h-6 w-6" /> },
  ] as const;

  return (
    <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-lg border-t border-slate-200/60 z-40 pb-safe shadow-[0_-8px_30px_rgb(0,0,0,0.04)]">
      <div className="max-w-md mx-auto flex justify-around items-center px-4 h-20">
        {navItems.map((item) => {
          const isActive = view === item.id;
          return (
            <button
              key={item.id}
              onClick={() => setView(item.id)}
              className={`flex flex-col items-center justify-center gap-1.5 transition-all duration-300 w-20 relative ${
                isActive ? 'text-primary' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              <div className={`transition-transform duration-300 ${isActive ? 'scale-110 -translate-y-1' : ''}`}>
                {item.icon}
              </div>
              <span className={`text-[10px] font-black uppercase tracking-widest transition-opacity ${isActive ? 'opacity-100' : 'opacity-70'}`}>
                {item.label}
              </span>

              {isActive && (
                <div className="absolute -bottom-1 w-1.5 h-1.5 bg-primary rounded-full shadow-sm shadow-primary/40" />
              )}
            </button>
          );
        })}
      </div>
    </nav>
  );
};

import React, { useState, useMemo } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';

export default function App() {
  const { 
    books, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter,
    customRange,
    setCustomRange 
  } = useBookData();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();

  const handleAddBook = (newBook: NewBook) => {
    addBook(newBook);
    setIsModalOpen(false);
    setEditingBook(null);
  };

  const handleUpdateBook = (updatedBook: Book) => {
    updateBook(updatedBook);
    setIsModalOpen(false);
    setEditingBook(null);
  };

  const openAddModal = (defaultStatus?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(defaultStatus);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingBook(null);
    setDefaultStatusForModal(undefined);
  };

  const shelfBooks = useMemo(() => books.filter(book => book.status !== BookStatus.Wishlist), [books]);
  const wishlistBooks = useMemo(() => books.filter(book => book.status === BookStatus.Wishlist), [books]);

  const [isFading, setIsFading] = useState(false);

  const handleSetView = (newView: 'dashboard' | 'list' | 'wishlist') => {
    if (view !== newView) {
      setIsFading(true);
      setTimeout(() => {
        setView(newView);
        setIsFading(false);
      }, 200);
    }
  };

  const renderContent = () => {
    switch(view) {
      case 'dashboard':
        return <Dashboard 
                  stats={stats} 
                  currentlyReading={currentlyReading} 
