            <div className="flex items-center gap-3">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Filtrar por Gênero:</span>
              {selectedGenres.length > 0 && (
                <button 
                  onClick={() => setSelectedGenres([])}
