import { useState, useMemo, useCallback, useEffect } from 'react';
import type { Book, ReadingStats, NewBook, DateFilter, MonthlyStat, TypeStat } from '../types';
import { BookStatus, BookType } from '../types';
import { dbService } from '../services/database';

const INITIAL_BOOKS: Book[] = [
  {
    id: '1',
    title: 'O Senhor dos Anéis - A Sociedade do Anel',
    author: 'J.R.R. Tolkien',
    pages: 434,
    genre: 'Aventura, Fantasia',
    type: BookType.Book,
    status: BookStatus.Reading,
    currentPage: 152,
    dateAdded: '2024-01-15',
    dateStarted: '2024-01-10',
    coverImageUrl: 'https://picsum.photos/seed/lotr/400/600',
    summary: 'Em uma terra fantástica e única, um hobbit recebe de presente de seu tio um anel mágico e maligno.',
  }
];

const MONTHS = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

// Hook to manage book data, statistics, and persistence
export const useBookData = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [dateFilter, setDateFilter] = useState<DateFilter>('allTime');
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [customRange, setCustomRange] = useState({ 
    start: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const loadData = useCallback(async () => {
    setIsLoading(true);
    try {
      const storedBooks = await dbService.getAllBooks();
      if (storedBooks.length === 0) {
        setBooks(INITIAL_BOOKS);
      } else {
        setBooks(storedBooks);
      }
    } catch (error) {
      console.error('DB Load Error:', error);
      setBooks(INITIAL_BOOKS);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // Calculate available years for filtering based on finished books or registration date
  const availableYears = useMemo(() => {
    const years = new Set<number>();
    years.add(new Date().getFullYear());
    books.forEach(b => {
      const year = b.dateFinished ? new Date(b.dateFinished).getFullYear() : (b.yearRead || new Date(b.dateAdded).getFullYear());
      if (year) years.add(year);
    });
    return Array.from(years).sort((a, b) => b - a);
  }, [books]);

  // Generate statistics based on selected date filters
  const stats: ReadingStats = useMemo(() => {
    const filtered = books.filter(b => {
      if (b.status !== BookStatus.Read) return false;
      const date = b.dateFinished ? new Date(b.dateFinished) : null;
      if (!date) return false;

      if (dateFilter === 'thisYear') {
        return date.getFullYear() === new Date().getFullYear();
      }
      if (dateFilter === 'specificYear') {
        return date.getFullYear() === selectedYear;
      }
      if (dateFilter === 'custom') {
        const start = new Date(customRange.start);
        const end = new Date(customRange.end);
        return date >= start && date <= end;
      }
      return true; // allTime
    });

    const yearly = {
      booksRead: filtered.length,
      pagesRead: filtered.reduce((acc, b) => acc + (b.pages || 0), 0),
      avgRating: filtered.length > 0 ? filtered.reduce((acc, b) => acc + (b.rating || 0), 0) / filtered.length : 0
    };

    const monthly: MonthlyStat[] = MONTHS.map((m, idx) => {
      const monthBooks = filtered.filter(b => {
        const date = b.dateFinished ? new Date(b.dateFinished) : null;
        return date && date.getMonth() === idx;
      });
      return {
        month: m,
        booksRead: monthBooks.length,
        pagesRead: monthBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
        avgRating: monthBooks.length > 0 ? monthBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / monthBooks.length : 0
      };
    });

    const byType: TypeStat[] = [BookType.Book, BookType.HQ].map(type => {
      const typeBooks = filtered.filter(b => b.type === type);
      return {
        type,
        count: typeBooks.length,
        pages: typeBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
        avgRating: typeBooks.length > 0 ? typeBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / typeBooks.length : 0
      };
    });

    return {
      tbrCount: books.filter(b => b.status === BookStatus.TBR).length,
      wishlistCount: books.filter(b => b.status === BookStatus.Wishlist).length,
      yearly,
      monthly,
      byType
    };
  }, [books, dateFilter, selectedYear, customRange]);

  const currentlyReading = useMemo(() => {
    return books.find(b => b.status === BookStatus.Reading) || null;
  }, [books]);

  const addBook = async (newBook: NewBook) => {
    const book: Book = {
      ...newBook,
      id: crypto.randomUUID(),
      dateAdded: new Date().toISOString().split('T')[0]
    };
    await dbService.saveBook(book);
    setBooks(prev => [book, ...prev]);
  };

  const updateBook = async (updatedBook: Book) => {
    await dbService.saveBook(updatedBook);
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
  };

  const deleteBook = async (id: string) => {
    await dbService.deleteBook(id);
    setBooks(prev => prev.filter(b => b.id !== id));
  };

  return {
    books,
    stats,
    currentlyReading,
    addBook,
    updateBook,
    deleteBook,
    dateFilter,
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLoading
  };
};

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

// Initialize GoogleGenAI with process.env.API_KEY directly as per guidelines.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateBookSummary = async (title: string, author: string): Promise<string> => {
  if (!process.env.API_KEY) return "AI-powered summaries are currently unavailable.";
  try {
    const prompt = `Write a short, engaging, one-paragraph summary in Portuguese for the book titled "${title}" by ${author}. Do not include spoilers.`;
    // Using gemini-3-flash-preview for text generation tasks.
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    // Extracting text output directly from property.
    return response.text || "Não foi possível gerar um resumo.";
  } catch (error) {
    console.error("Error generating book summary:", error);
    return "Erro ao gerar resumo. Tente novamente.";
  }
};

export const generateBookCover = async (title: string, genre: string, type: string): Promise<string> => {
  if (!process.env.API_KEY) return `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`;
  try {
    const prompt = `Create a minimalist, abstract book cover for a ${type} titled "${title}" in the ${genre} genre. The style should be elegant and modern, focusing on symbolic imagery rather than literal depiction. High contrast, clean typography.`;

    // Using gemini-2.5-flash-image for image generation tasks via generateContent.
    const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
            parts: [{ text: prompt }]
        },
        config: {
            imageConfig: {
                aspectRatio: "3:4"
            }
        }
    });

    // Finding the image part in response parts.
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
              const base64EncodeString: string = part.inlineData.data;
              return `data:image/png;base64,${base64EncodeString}`;
          }
      }
    }

    // Fallback if no image part is found
    return `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`;

  } catch (error) {
    console.error("Error generating book cover:", error);
    return `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`;
  }
};

import type { Book } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const LOCAL_STORAGE_KEY = 'biblio_tech_local_db';

export class DatabaseService {
  private useLocalStorage = false;

  private getLocalBooks(): Book[] {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  private saveLocalBooks(books: Book[]): void {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(books));
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        // Erro 42P01 ou PGRST116 indica que a tabela não existe
        if (error.code === '42P01' || error.message.includes('not find the table')) {
          this.logSchemaAdvice();
          this.useLocalStorage = true;
          return this.getLocalBooks();
        }
        throw error;
      }

      this.useLocalStorage = false;
      return (data as Book[]) || [];
    } catch (err: any) {
      console.warn('Usando armazenamento local (Offline Mode):', err.message);
      this.useLocalStorage = true;
      return this.getLocalBooks();
    }
  }

  async saveBook(book: Book): Promise<void> {
    if (this.useLocalStorage) {
      const books = this.getLocalBooks();
      const index = books.findIndex(b => b.id === book.id);
      if (index >= 0) {
        books[index] = book;
      } else {
        books.unshift(book);
      }
      this.saveLocalBooks(books);
      return;
    }

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert(book);

      if (error) throw error;
    } catch (err: any) {
      console.error('Erro ao sincronizar com Supabase, salvando localmente:', err.message);
      const books = this.getLocalBooks();
      books.unshift(book);
      this.saveLocalBooks(books);
    }
  }

  async deleteBook(id: string): Promise<void> {
    if (this.useLocalStorage) {
      const books = this.getLocalBooks().filter(b => b.id !== id);
      this.saveLocalBooks(books);
      return;
    }

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) throw error;
    } catch (err: any) {
      console.error('Erro ao deletar no Supabase:', err.message);
    }
  }

  private logSchemaAdvice() {
    console.log(`
%c 💡 DICA DE INTEGRAÇÃO SUPABASE 
%c Execute este comando no seu SQL Editor do Supabase para criar a tabela:

create table books (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  author text not null,
  pages integer default 0,
  genre text,
  type text,
  status text,
  rating integer,
  coverImageUrl text,
  summary text,
  yearRead integer,
  monthRead text,
  estimatedPrice numeric,
  buyLink text,
  currentPage integer default 0,
  dateAdded timestamp with time zone default now(),
  dateStarted timestamp with time zone,
  dateFinished timestamp with time zone
);

%c Após executar, atualize esta página.`, 
'color: #2563eb; font-weight: bold; font-size: 14px;', 
'color: #475569; font-size: 12px;',
'color: #2563eb; font-weight: bold;');
  }
}

