      books[index] = book;
    } else {
      books.unshift(book);
    }
    this.saveLocalBooks(books);
  }

  async deleteBook(id: string): Promise<void> {
    if (this.useLocalStorage) {
      const books = this.getLocalBooks().filter(b => b.id !== id);
      this.saveLocalBooks(books);
      return;
    }

